"use client";
import { useEffect,useState } from "react"; import { AnimatePresence,motion } from "framer-motion"; import { Menu,X,ArrowUpRight } from "lucide-react"; import { nav,site } from "@/data/site";
export default function Header(){const [scrolled,setScrolled]=useState(false),[open,setOpen]=useState(false);useEffect(()=>{const fn=()=>setScrolled(scrollY>40);fn();addEventListener("scroll",fn,{passive:true});return()=>removeEventListener("scroll",fn)},[]);useEffect(()=>{document.body.style.overflow=open?"hidden":"";return()=>{document.body.style.overflow=""}},[open]);return <header className={`header ${scrolled?"is-scrolled":""}`}><a className="wordmark" href="#top" aria-label="Dicey's home">DICEY&apos;S<small>GOOD FOOD · BETTER POURS</small></a><nav aria-label="Primary">{nav.map(x=><a key={x} href={`#${x.toLowerCase()}`}>{x}</a>)}</nav><a className="nav-cta" href={site.mapsUrl} target="_blank">Find us <ArrowUpRight size={15}/></a><button className="menu-button" onClick={()=>setOpen(!open)} aria-label="Open menu" aria-expanded={open}>{open?<X/>:<Menu/>}</button><AnimatePresence>{open&&<motion.div className="mobile-menu" initial={{clipPath:"inset(0 0 100% 0)"}} animate={{clipPath:"inset(0 0 0% 0)"}} exit={{clipPath:"inset(0 0 100% 0)"}} transition={{duration:.6,ease:[.76,0,.24,1]}}>{nav.map((x,i)=><motion.a initial={{opacity:0,y:25}} animate={{opacity:1,y:0}} transition={{delay:.12+i*.05}} onClick={()=>setOpen(false)} key={x} href={`#${x.toLowerCase()}`}>{x}</motion.a>)}<p>Golf Club Road · Bengaluru</p></motion.div>}</AnimatePresence></header>}
